INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Erstuntersuchung und umfassende Behandlungsplanung',
'<p>Eine umfassende Erstuntersuchung bedeutet, das Anliegen anzuhören, die medizinische und zahnmedizinische Vorgeschichte zu erheben, Mundhöhle und umgebende Gewebe klinisch zu beurteilen und nur die als notwendig erachteten Aufnahmen gemeinsam auszuwerten. Der Behandlungsplan wird auf dieser Grundlage, den Prioritäten der Patientin oder des Patienten und den geeigneten Optionen schrittweise erstellt.</p>
<p><img src="/assets/uploads/images/ts18-ilk-dis-muayenesi-gorusme.webp" alt="Das Anliegen und die Erwartungen der Patientin bei der Erstuntersuchung anhören" loading="lazy"  /></p>
<h2>Anliegen und Erwartungen</h2>
<p>Schmerzen, ästhetische Erwartungen, Schwierigkeiten beim Kauen, fehlende Zähne, vorhandene Restaurationen und Prioritäten werden mit den eigenen Worten der Patientin oder des Patienten festgehalten. Das erste Ziel ist nicht, einen Eingriff auszuwählen, sondern die Bedürfnisse und die Entscheidungskriterien zu verstehen.</p>
<h2>Medizinische und zahnmedizinische Vorgeschichte</h2>
<p>Allgemeinerkrankungen, Allergien, eine mögliche Schwangerschaft, frühere Operationen und Behandlungen, eingenommene Medikamente und frühere zahnärztliche Erfahrungen werden erfragt. Bei Bedarf wird die Einschätzung der behandelnden Ärztin oder des behandelnden Arztes eingeholt; Medikamente sollten nicht eigenmächtig abgesetzt werden. Zur Behandlungsplanung in der Schwangerschaft sehen Sie die Seite <a href="/de/hamilelikte-dis-tedavisi/">Zahnbehandlung in der Schwangerschaft</a>.</p>
<h2>Extraorale und Weichgewebsuntersuchung</h2>
<p>Gesichtssymmetrie, Kieferbewegungen, Lymphknoten und relevante extraorale Befunde sowie die Weichgewebe wie Lippen, Wangen, Zunge, Gaumen und Mundboden werden systematisch beurteilt. Wird ein auffälliger Befund festgestellt, werden eine weiterführende Abklärung und die erforderlichen Untersuchungen veranlasst.</p>
<h2>Zähne und vorhandene Restaurationen</h2>
<p>Verdacht auf <a href="/de/dis-curugu-kompozit-dolgu/">Karies</a>, Frakturen und Abnutzungen, Farbveränderungen, Empfindlichkeit, Zahnbeweglichkeit, der Zustand von Füllungen, Kronen und Brücken sowie Bereiche mit fehlenden Zähnen werden anhand klinischer Befunde beurteilt. Bei Bedarf kommen Sensibilitäts- und weitere Hilfstests hinzu.</p>
<p><img src="/assets/uploads/images/ts18-kapsamli-agiz-dis-muayenesi.webp" alt="Systematische Untersuchung von Zähnen, Zahnfleisch und Mundgeweben" loading="lazy"  /></p>
<h2>Zahnfleisch und parodontale Beurteilung</h2>
<p>Plaque und Zahnstein, Blutung, Zahnfleischrückgang, Taschentiefe, die Stützgewebe und Risikoindikatoren werden beurteilt. Die Zahnfleischgesundheit kann die Reihenfolge der Behandlung vor implantologischen, prothetischen oder ästhetischen Eingriffen verändern.</p>
<h2>Wie werden die Untersuchungsdaten gemeinsam genutzt?</h2>
<table>
<thead><tr><th>Aufzeichnung</th><th>Was sie beiträgt</th><th>Grundsatz der Nutzung</th></tr></thead>
<tbody>
<tr><td>Klinische Untersuchung</td><td>Befunde an Zähnen, Zahnfleisch, Weichgewebe, Kiefergelenk und Biss</td><td>Die Basisbeurteilung bei jeder Patientin und jedem Patienten, ihr Umfang richtet sich nach dem Bedarf</td></tr>
<tr><td>Röntgenaufnahme</td><td>Beurteilung von Wurzeln, Knochen und Zwischenräumen, die nicht sichtbar sind</td><td>Nur die Aufnahme, die nach Vorgeschichte, vorhandenen Unterlagen und klinischem Befund erforderlich ist</td></tr>
<tr><td>Fotos / digitaler Scan</td><td>Eine Aufzeichnung, die hilft, Ausgangslage, Zahnreihe und Biss zu dokumentieren</td><td>Nach Art der Behandlung und Planungsbedarf; für sich allein keine gesicherte Diagnose</td></tr>
</tbody>
</table>
<p><strong>Wichtig:</strong> Panoramaaufnahme, DVT, Fotos oder ein digitaler Scan sind kein automatisches Paket für jede Patientin und jeden Patienten. Datum und diagnostische Aussagekraft vorhandener Unterlagen werden beurteilt; neue Aufnahmen werden nur bei klinischer Notwendigkeit angefertigt.</p>
<p><img src="/assets/uploads/images/ts18-klinik-radyografik-dijital-degerlendirme.webp" alt="Klinische, röntgenologische und digitale Unterlagen gemeinsam beurteilt" loading="lazy"  /></p>
<h2>Biss, Gelenk und Funktion</h2>
<p>Zahnkontakte, die Kaubeziehung, die Mundöffnung, Gelenk- und Muskelbeschwerden sowie Abnutzungszeichen durch Pressen und Knirschen werden beurteilt. Ein einzelnes Geräusch oder eine Abnutzung bedeutet für sich genommen weder eine Erkrankung noch die Notwendigkeit einer Schiene.</p>
<h2>Wahl der Bildgebung</h2>
<p>Bissflügel-, Zahnfilm-, Panorama- oder dreidimensionale Aufnahmen werden nach den Untersuchungsbefunden und dem geplanten Eingriff gewählt. Ein DVT wird nicht bei jeder Patientin und jedem Patienten eingesetzt; der erwartete diagnostische Nutzen wird gegen die Strahlenexposition abgewogen.</p>
<h2>Die Rolle digitaler Aufzeichnungen</h2>
<p>Mit einem Intraoralscanner erstellte Aufnahmen, standardisierte Fotos und digitale Modelle können helfen, Ausgangslage, Biss und restaurativen Plan zu dokumentieren. Softwareergebnisse ersetzen nicht die zahnärztliche Untersuchung und die klinische Überprüfung.</p>
<h2>Diagnose und Risikobeurteilung</h2>
<p>Karies, Zahnfleischerkrankungen, Probleme an Pulpa und Wurzelspitze, Frakturrisiko, Hygiene, Rauchen, Ernährung und Pflegegewohnheiten werden gemeinsam betrachtet. Für nicht gesicherte Befunde können Beobachtung oder zusätzliche Untersuchungen vorgesehen werden.</p>
<h2>Der schrittweise Behandlungsplan</h2>
<ol>
<li>Kontrolle akuter Schmerzen und Infektionen</li>
<li>Stoppen der Erkrankung und Herstellung grundlegender Zahnfleischgesundheit</li>
<li>Definitive restaurative, chirurgische oder prothetische Schritte</li>
<li>Nachsorge und ein individuell festgelegtes Kontrollintervall</li>
</ol>
<p>Die klinische Situation kann diese Reihenfolge verändern. Was der Plan enthält und wie er aktualisiert wird, finden Sie auf der Seite <a href="/de/tedavi-plani-ve-surec/">Behandlungsplan und Ablauf</a>.</p>
<p><img src="/assets/uploads/images/ts18-asamali-tedavi-plani-ve-bilgilendirme.webp" alt="Den schrittweisen Behandlungsplan der Patientin erläutern" loading="lazy"  /></p>
<h2>Optionen und Ablauf</h2>
<p>Zweck jeder anwendbaren Option, ihre wesentlichen Vorteile und Risiken, die Alternativen, die möglichen Folgen einer Nichtbehandlung sowie die voraussichtliche Dauer und der Umfang werden verständlich besprochen. Der Plan kann aufgrund neuer klinischer Befunde oder des Heilungsverlaufs angepasst werden. Die aufgeklärte Einwilligung ist nicht bloß eine Unterschrift; sie ist ein Prozess verständlicher Aufklärung und der Möglichkeit, Fragen zu stellen.</p>
<h2>Häufig gestellte Fragen</h2>
<p><strong>Wird bei der Erstuntersuchung sofort behandelt?</strong><br>Nicht immer. Vorrang haben Beurteilung und sichere Planung. Akute Schmerzen oder ein geeigneter einfacher Eingriff können bei ausreichender Zeit und Einwilligung noch am selben Tag versorgt werden. Eine umfassende Behandlung beginnt meist nach der Planung.</p>
<p><strong>Wird von jeder Patientin und jedem Patienten eine Panoramaaufnahme verlangt?</strong><br>Nein. Art und Zeitpunkt der Bildgebung richten sich nach Vorgeschichte, klinischer Untersuchung, vorhandenen Aufnahmen und dem geplanten Eingriff. Sind vorhandene Unterlagen ausreichend, wird nicht unnötig wiederholt.</p>
<p><strong>Wie werden die Prioritäten im Behandlungsplan festgelegt?</strong><br>Notfallversorgung und Infektionskontrolle kommen zuerst; nach Abschluss grundlegender Schritte wie Zahnfleisch- und Kariesbehandlung werden definitive Restaurationen, Implantate und Zahnersatz oder ästhetische Eingriffe geplant.</p>
<p><strong>Kann ich für eine Zweitmeinung meine vorhandenen Unterlagen mitbringen?</strong><br>Ja. Röntgenaufnahmen, Befunde, Implantatangaben und frühere Behandlungsunterlagen können die Beurteilung erleichtern. Sind sie jedoch nicht aktuell oder die Bildqualität unzureichend, können zusätzliche Aufnahmen nötig sein.</p>
<h2>Regionale Beurteilung</h2>
<p>In unserer Praxis an der Verbindung Beylikdüzü–Esenyurt wird die Erstuntersuchung als umfassender Planungsprozess verstanden, in dem Anliegen, Krankengeschichte, Zahn- und Zahnfleischgesundheit, Biss sowie nur die erforderlichen klinischen und digitalen Aufzeichnungen gemeinsam beurteilt werden.</p>
<p><a href="/de/acil-dis-agrisinda-ilk-24-saat/">Zahnärztliche Notfälle</a> &middot; <a href="/de/tedavi-plani-ve-surec/">Behandlungsplan und Ablauf</a> &middot; <a href="/de/dental-implant-tedavisi/">Zahnimplantat-Behandlung</a> &middot; <a href="/de/iletisim">Termin und Kontakt</a></p>',
'Krankengeschichte, Beurteilung von Zahnfleisch und Biss, erforderliche Röntgenaufnahmen, digitale Unterlagen und der schrittweise Behandlungsplan.',
'Erstuntersuchung und Behandlungsplan | MSc. Dt. Mehmet Taş',
'DE' FROM pages WHERE link = 'ilk-dis-muayenesi-tedavi-planlamasi';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Behandlungsplan und Transparenz: Was bestimmt den Umfang?',
'<p>Bei einer Zahnbehandlung erzeugt Ungewissheit oft mehr Sorge als die Behandlung selbst. Wenn nach der Untersuchung schriftlich mitgeteilt wird, welche Eingriffe erfolgen, in wie vielen Schritten und in welcher Reihenfolge, kann die Patientin oder der Patient auf Grundlage von Informationen entscheiden. Diese Seite erklärt, wie der Ablauf funktioniert, bevor Sie in die Praxis kommen.</p>
<p><img src="/assets/uploads/images/ts90-01-tedavi-plani-gorusmesi.webp" alt="Der Zahnarzt bespricht den Behandlungsplan mit der Patientin" loading="lazy"  /></p>
<h2>Was enthält ein Behandlungsplan?</h2>
<table>
<thead><tr><th>Abschnitt</th><th>Erläuterung</th></tr></thead>
<tbody>
<tr><td>Klinische Befunde</td><td>Der durch Untersuchung und erforderliche Bildgebung festgestellte Zustand.</td></tr>
<tr><td>Empfohlene Eingriffe</td><td>Welcher Eingriff an welchem Zahn empfohlen wird, verständlich dargestellt.</td></tr>
<tr><td>Alternativen</td><td>Andere Vorgehensweisen für dasselbe Problem und die Unterschiede dazwischen.</td></tr>
<tr><td>Schritte und Reihenfolge</td><td>Welcher Eingriff zuerst erfolgen muss und warum.</td></tr>
<tr><td>Voraussichtlicher Ablauf</td><td>Ungefähre Zahl der Sitzungen und die für die Heilung erwarteten Wartezeiten.</td></tr>
<tr><td>Was geschieht ohne Behandlung?</td><td>Der zu erwartende Verlauf, wenn die Behandlung aufgeschoben wird.</td></tr>
<tr><td>Pflegebedarf</td><td>Was nach der Behandlung an Kontrollen und täglicher Pflege erwartet wird.</td></tr>
</tbody>
</table>
<p>Bei umfassenden Plänen werden diese Angaben neben der mündlichen Erläuterung auch schriftlich mitgeteilt; so bleibt Zeit zum Nachdenken und für Rückfragen.</p>
<h2>Was bestimmt den Umfang des Plans?</h2>
<p>Zwei Menschen mit demselben Anliegen haben nicht zwangsläufig denselben Behandlungsplan. Die wichtigsten Faktoren für den Umfang sind:</p>
<ul>
<li>Art des Problems, seine Ausbreitung und wie weit es fortgeschritten ist</li>
<li>Die verbliebene gesunde Zahnsubstanz und der Zustand von Zahnfleisch- und Knochenhalt</li>
<li>Bissverhältnis sowie Pressen und Knirschen</li>
<li>Allgemeinzustand, eingenommene Medikamente, Rauchverhalten</li>
<li>Mundpflegegewohnheiten und die Möglichkeit, Kontrolltermine wahrzunehmen</li>
<li>Das gewählte Verfahren, das verwendete Material und die Laborphase</li>
<li>Der Bedarf an Vorbehandlungen (Zahnfleischbehandlung, Knochenaufbau, kieferorthopädische Vorbereitung und Ähnliches)</li>
</ul>
<p>Ohne Untersuchung kann kein Plan erstellt werden. Verbindliche Angaben zu Behandlung und Umfang, die telefonisch, per Nachricht oder anhand eines Fotos gemacht werden, sind nicht verlässlich. Ein Vorgespräch vermittelt nur einen allgemeinen Eindruck; der Plan entsteht nach klinischer Untersuchung und erforderlicher Bildgebung.</p>
<p><img src="/assets/uploads/images/ts90-03-muayene-ve-degerlendirme.webp" alt="Untersuchung und röntgenologische Beurteilung gemeinsam durchgeführt" loading="lazy"  /></p>
<h2>Schrittweise Planung und Reihenfolge</h2>
<p>Bei umfassenden Behandlungen wird nicht alles gleichzeitig erledigt. Im Allgemeinen gilt folgende Reihenfolge:</p>
<table>
<thead><tr><th>Schritt</th><th>Inhalt</th></tr></thead>
<tbody>
<tr><td>1 — Notfall</td><td>Situationen, die nicht warten können: Schmerzen, Infektion, Schwellung und Unfälle.</td></tr>
<tr><td>2 — Stoppen der Erkrankung</td><td><a href="/de/dis-curugu-kompozit-dolgu/">Kariesbehandlung</a>, Zahnfleischbehandlung, Ordnen der Mundpflege.</td></tr>
<tr><td>3 — Wiederaufbau</td><td>Füllungen, Kronen, <a href="/de/kanal-tedavisi/">Wurzelkanalbehandlung</a>, <a href="/de/dental-implant-tedavisi/">Ersatz fehlender Zähne</a>.</td></tr>
<tr><td>4 — Ästhetik</td><td>Nicht zwingende ästhetische Eingriffe, nachdem die gesundheitlichen Probleme gelöst sind.</td></tr>
<tr><td>5 — Vorbeugung und Nachsorge</td><td>Regelmäßige Kontrollen, Reinigung und bei Bedarf eine Nachtschiene.</td></tr>
</tbody>
</table>
<p>Diese Reihenfolge soll sicherstellen, dass der Untergrund tragfähig ist, auf dem die Arbeit aufbaut. Das Langzeitergebnis einer ästhetischen Restauration, die bei bestehender Zahnfleischentzündung eingesetzt wird, kann beeinträchtigt werden.</p>
<p><img src="/assets/uploads/images/ts90-02-asamali-planlama.webp" alt="Schema des in Schritte gegliederten Behandlungsplans" loading="lazy"  /></p>
<h2>Kann sich der Plan ändern?</h2>
<p>Ja. In der Zahnmedizin werden manche Befunde erst während des Eingriffs sichtbar: Die Tiefe einer Karies etwa zeigt sich erst beim Entfernen, und der Bedarf an einer Wurzelkanalbehandlung kann sich ergeben. In solchen Fällen wird die Patientin oder der Patient informiert und die Einwilligung eingeholt, bevor weitergearbeitet wird. Eine Anpassung des Plans bedeutet nicht, dass die ursprüngliche Beurteilung falsch war.</p>
<h2>Die türkische Sozialversicherung und Zahnbehandlungen</h2>
<p>Die Ansprüche auf zahnärztliche Behandlung im Rahmen der türkischen Sozialversicherungsanstalt (SGK) richten sich danach, bei welcher Art von Einrichtung man sich vorstellt. Leistungen der Mund- und Zahngesundheit werden in öffentlichen Gesundheitseinrichtungen und in Einrichtungen mit SGK-Vertrag im gesetzlich festgelegten Umfang erbracht.</p>
<p><strong>Unsere Praxis hat keinen Vertrag mit der Sozialversicherungsanstalt.</strong> Diese Angabe steht hier ausdrücklich, weil sie vor einer Terminvereinbarung bekannt sein sollte. Ändern sich die gesetzlichen Vorgaben oder die Vertragslage, wird dieser Abschnitt aktualisiert.</p>
<h2>Fragen, die Sie Ihrer Zahnärztin oder Ihrem Zahnarzt stellen können</h2>
<ul>
<li>Welche Eingriffe werden in meinem Fall empfohlen und warum?</li>
<li>Welche Alternativen gibt es zu dieser Behandlung? Worin unterscheiden sie sich?</li>
<li>Was muss jetzt geschehen und was kann warten?</li>
<li>Wie viele Sitzungen sind zu erwarten? Wie lange dauert es zwischen den Sitzungen?</li>
<li>Was ist danach normal zu spüren und wann sollte ich Sie anrufen?</li>
<li>Was geschieht, wenn ich diese Behandlung nicht durchführen lasse?</li>
<li>Welche Pflege und welche Kontrollen sind danach nötig?</li>
<li>Kann ich Informationen zum verwendeten Material erhalten?</li>
<li>Wie werde ich informiert, wenn sich der Plan während der Behandlung ändert?</li>
</ul>
<h2>Ihre personenbezogenen Daten</h2>
<p>Angaben, die bei Untersuchung, Bildgebung und Behandlung erhoben werden, sind besondere Kategorien personenbezogener Daten. Zu welchem Zweck diese Daten verarbeitet werden, wie lange sie gespeichert bleiben und welche Rechte Sie haben, wird in der <a href="/de/sayfa/kvkk-aydinlatma-metni">Datenschutzerklärung</a> erläutert. Über das Terminformular werden keine ausführlichen Gesundheitsangaben oder Bilder angefordert; bei Bedarf wird ein sicherer Weg gesondert mitgeteilt.</p>
<h2>Häufig gestellte Fragen</h2>
<p><strong>Kann ich den Behandlungsumfang telefonisch erfahren?</strong><br>Da der Umfang ohne Untersuchung nicht bestimmt werden kann, sind telefonisch keine verbindlichen Angaben möglich. Nach der Untersuchung wird Ihnen ein individueller Plan schriftlich mitgeteilt.</p>
<p><strong>Kann ich mir Zeit nehmen, um über den Plan nachzudenken?</strong><br>Ja. Wenn kein Notfall vorliegt, ist es völlig üblich, sich Zeit zu nehmen. Ihre Fragen können Sie uns auch später zukommen lassen.</p>
<p><strong>Darf ich die Meinung einer anderen Zahnärztin oder eines anderen Zahnarztes einholen?</strong><br>Ja. Eine Zweitmeinung einzuholen ist Ihr Recht. Auf Wunsch können Ihre vorhandenen Unterlagen weitergegeben werden.</p>
<p><strong>Was geschieht, wenn sich der Plan während der Behandlung ändert?</strong><br>Bevor weitergearbeitet wird, wird die Situation erläutert, die Optionen werden besprochen und Ihre Einwilligung wird eingeholt.</p>
<p><strong>Was soll ich zum Termin mitbringen?</strong><br>Einen Ausweis, vorhandene frühere Röntgenaufnahmen und Behandlungsunterlagen, eine Liste Ihrer Medikamente sowie Angaben zu bekannten Erkrankungen oder Allergien. Liegt ein Befund einer anderen Behandlerin oder eines anderen Behandlers vor, bringen Sie ihn bitte mit.</p>
<p><strong>Erhalte ich eine Rechnung und Unterlagen?</strong><br>Für die durchgeführten Leistungen erfolgt eine den gesetzlichen Vorgaben entsprechende Dokumentation. Auf Wunsch erhalten Sie eine Kopie Ihrer Behandlungsunterlagen.</p>
<h2>Regionale Beurteilung</h2>
<p>In unserer Praxis an der Verbindung Beylikdüzü–Esenyurt entsteht der Behandlungsplan durch die gemeinsame Beurteilung von klinischer Untersuchung, erforderlicher Bildgebung und den Erwartungen der Patientin oder des Patienten und wird mit ihr oder ihm besprochen.</p>
<p><a href="/de/dental-implant-tedavisi/">Zahnimplantat-Behandlung</a> &middot; <a href="/de/kanal-tedavisi/">Wurzelkanalbehandlung</a> &middot; <a href="/de/sayfa/kvkk-aydinlatma-metni">Datenschutzerklärung</a> &middot; <a href="/de/iletisim">Termin und Kontakt</a></p>',
'Was enthält ein Behandlungsplan und was bestimmt seinen Umfang? Was Sie vor dem Termin wissen sollten und welche Fragen Sie stellen können.',
'Behandlungsplan und Transparenz | MSc. Dt. Mehmet Taş',
'DE' FROM pages WHERE link = 'tedavi-plani-ve-surec';


INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Zahnärztliche Notfälle: Was in den ersten 24 Stunden zu tun ist',
'<p><strong>Haben Sie gerade Schmerzen?</strong> <a href="tel:+905435588519">+90 543 558 85 19</a> &middot; <a href="https://wa.me/905435588519" target="_blank" rel="noopener">WhatsApp</a> &middot; <a href="https://www.google.com/maps/dir/?api=1&amp;destination=41.0173894%2C28.6465901" target="_blank" rel="noopener">Anfahrt</a></p>
<p>Starke Zahnschmerzen vergehen meist nicht von selbst; dass der Schmerz nachlässt, bedeutet nicht, dass das Problem behoben ist. In den ersten 24 Stunden geht es darum, den Schmerz sicher zu beherrschen und möglichst rasch einen Untersuchungstermin zu bekommen. Die folgenden Hinweise dienen der Information und ersetzen keine Untersuchung.</p>
<h2>Was Sie sofort tun können</h2>
<ul>
<li>Sie können den Mund vorsichtig mit lauwarmem Wasser spülen.</li>
<li>Sitzen Speisereste im schmerzenden Bereich fest, können Sie vorsichtig versuchen, sie mit Zahnseide zu entfernen.</li>
<li>Eine Kühlung von außen an der Wange (in ein Tuch gewickeltes Eis, im Abstand von 10–15 Minuten) kann helfen, Schwellung und Schmerz zu verringern.</li>
<li>Den Kopf beim Liegen etwas höher zu lagern kann Erleichterung bringen, besonders bei nachts zunehmenden pochenden Schmerzen.</li>
<li>Wenn Sie ein Schmerzmittel einnehmen, wählen Sie eines, das Ihnen zuvor ärztlich oder in der Apotheke empfohlen wurde und für Sie unbedenklich ist, und überschreiten Sie die Dosis auf der Packung nicht.</li>
</ul>
<p><img src="/assets/uploads/images/ts83-05-soguk-uygulama.webp" alt="Kühlung mit einem in ein Tuch gewickelten Umschlag von außen an der Wange bei Zahnschmerzen" loading="lazy"  /></p>
<h2>Was Sie vermeiden sollten</h2>
<ul>
<li><strong>Nehmen Sie keine Antibiotika ohne Verordnung ein.</strong> Antibiotika beseitigen die Schmerzursache nicht; sie verdecken das Bild vorübergehend, erschweren die Diagnose, und unnötige Einnahme trägt zur Entstehung von Resistenzen bei.</li>
<li>Legen Sie keine Aspirin- oder Schmerztabletten, kein Kölnischwasser, keinen Alkohol und keinen Essig auf den schmerzenden Zahn oder das Zahnfleisch; das kann eine chemische Verätzung des Zahnfleischs verursachen.</li>
<li>Wenden Sie bei einer Schwellung keine Wärme an; warme Umschläge können die Ausbreitung der Entzündung begünstigen.</li>
<li>Versuchen Sie nicht, einen Abszess selbst zu öffnen oder auszudrücken.</li>
<li>Kauen Sie keine harten Speisen auf der schmerzenden Seite.</li>
</ul>
<p><img src="/assets/uploads/images/ts83-06-kacinilmasi-gerekenler.webp" alt="Bei Zahnschmerzen zu vermeidende frei verkäufliche Medikamente und Wärmeanwendung" loading="lazy"  /></p>
<h2>Anzeichen, die ein sofortiges Vorstellen erfordern</h2>
<p>Liegt eines der folgenden Anzeichen vor, handelt es sich nicht allein um ein zahnärztliches Problem; Sie sollten sich ohne Zeitverlust in der <strong>nächstgelegenen Notaufnahme</strong> vorstellen. Warten Sie nicht auf einen Zahnarzttermin.</p>
<table>
<thead><tr><th>Anzeichen</th><th>Warum ist es dringend?</th></tr></thead>
<tbody>
<tr><td>Atem- oder Schluckbeschwerden</td><td>Eine Schwellung kann die Atemwege verengen. Das ist lebensbedrohlich; rufen Sie direkt den Rettungsdienst.</td></tr>
<tr><td>Sich ausbreitende Schwellung am Mundboden oder am Hals</td><td>Kann darauf hinweisen, dass die Infektion in die tiefen Halsräume fortgeschritten ist.</td></tr>
<tr><td>Schwellung, die sich zum Auge ausbreitet, oder ein zufallendes Augenlid</td><td>Kann darauf hinweisen, dass sich eine Infektion aus dem Oberkiefer nach oben ausbreitet.</td></tr>
<tr><td>Hohes Fieber, Schüttelfrost, Abgeschlagenheit</td><td>Kann darauf hinweisen, dass die Infektion den örtlichen Bereich überschritten hat.</td></tr>
<tr><td>Unfähigkeit, den Mund zu öffnen (Kieferklemme)</td><td>Kann darauf hinweisen, dass die Kaumuskulatur betroffen und die Infektion fortgeschritten ist.</td></tr>
<tr><td>Nicht stillbare Blutung</td><td>Besonders bei Einnahme von Gerinnungshemmern ist eine sofortige Beurteilung nötig.</td></tr>
</tbody>
</table>
<p><strong>Bei einem gebrochenen oder durch einen Schlag ausgeschlagenen Zahn:</strong> Fassen Sie den Zahn an der Krone an, reiben Sie nicht an der Wurzel; bewahren Sie ihn in Milch, Kochsalzlösung oder Speichel auf und stellen Sie sich schnellstmöglich vor. Die Zeit ist hier entscheidend. Ausführliche Hinweise für Kinder finden Sie auf der Seite <a href="/de/cocuklarda-dis-travmasi/">Zahnunfälle bei Kindern</a>.</p>
<h2>Was geschieht in der Praxis?</h2>
<p><img src="/assets/uploads/images/ts83-01-acil-degerlendirme-gorusmesi.webp" alt="Der Zahnarzt beurteilt eine Patientin, die als Notfall erscheint" loading="lazy"  /></p>
<table>
<thead><tr><th>Schritt</th><th>Was geschieht</th><th>Was zu erwarten ist</th></tr></thead>
<tbody>
<tr><td>Rasche Ersteinschätzung</td><td>Ort, Dauer, Art und Auslöser des Schmerzes werden erfragt</td><td>Feststellen, ob eine Notfallmaßnahme erforderlich ist</td></tr>
<tr><td>Klinische Untersuchung</td><td>Zahn, Zahnfleisch und umgebende Gewebe werden untersucht; ein Sensibilitätstest kann erfolgen</td><td>Bestimmung der Schmerzursache</td></tr>
<tr><td>Röntgenuntersuchung</td><td>Bei Bedarf wird eine Zahnfilm- oder Panoramaaufnahme angefertigt</td><td>Darstellung des Zustands von Wurzel und Knochen</td></tr>
<tr><td>Schmerzbeseitigung</td><td>Je nach Situation erfolgen eine Entlastung, das <a href="/de/kanal-tedavisi/">Eröffnen des Wurzelkanals</a> oder eine provisorische Versorgung</td><td>Der Schmerz wird unter Kontrolle gebracht</td></tr>
<tr><td>Vorstellung des Plans</td><td>Die definitiven Behandlungsoptionen und der Zeitplan werden erläutert</td><td>Schriftliche Informationen für die nächsten Schritte</td></tr>
</tbody>
</table>
<p><img src="/assets/uploads/images/ts83-02-panoramik-rontgen-incelemesi.webp" alt="Auswertung einer Panoramaaufnahme zur Bestimmung der Schmerzursache" loading="lazy"  /></p>
<p>Bei Notfallvorstellungen haben die Schmerzbeseitigung und die Kontrolle der Infektion Vorrang. Die definitive Behandlung wird meist in Terminen nach Abklingen des akuten Zustands geplant; Einzelheiten finden Sie auf der Seite <a href="/de/tedavi-plani-ve-surec/">Behandlungsplan und Ablauf</a>.</p>
<p><img src="/assets/uploads/images/ts83-03-brosurle-bilgilendirme.webp" alt="Erläuterung der Behandlungsoptionen anhand einer Broschüre" loading="lazy"  /></p>
<p><img src="/assets/uploads/images/ts83-04-takip-ve-kontrol-plani.webp" alt="Besprechung des Kontroll- und Nachsorgeplans nach der Behandlung" loading="lazy"  /></p>
<h2>Anfahrt und Termin</h2>
<p>In unserer Praxis an der Verbindung Beylikdüzü–Esenyurt werden Notfallvorstellungen beurteilt; auch Patientinnen und Patienten aus Büyükçekmece und den umliegenden Bezirken gehören dazu. Uns vor Ihrem Kommen telefonisch oder über WhatsApp zu erreichen ist wichtig, damit wir uns vorbereiten und Ihnen sagen können, was Sie unterwegs tun sollten.</p>
<p><strong>Außerhalb der Sprechzeiten:</strong> Unsere diensthabende Zahnärztin oder unser diensthabender Zahnarzt nimmt bei Vorstellungen außerhalb der Sprechzeiten und in Notfällen die Ersteinschätzung vor und beginnt die Behandlung. Liegen die oben genannten Notfallzeichen vor, warten Sie nicht, sondern stellen Sie sich in der nächstgelegenen Notaufnahme vor.</p>
<p><a href="tel:+905435588519">+90 543 558 85 19</a> &middot; <a href="https://wa.me/905435588519" target="_blank" rel="noopener">WhatsApp</a> &middot; <a href="https://www.google.com/maps/dir/?api=1&amp;destination=41.0173894%2C28.6465901" target="_blank" rel="noopener">Anfahrt</a></p>
<h2>Häufig gestellte Fragen</h2>
<p><strong>Ich habe ein Schmerzmittel genommen und der Schmerz ist weg — soll ich trotzdem kommen?</strong><br>Ja. Ein Schmerzmittel unterdrückt nur das Schmerzsignal, es beseitigt nicht die zugrunde liegende Ursache. Gerade wenn der Zahnnerv betroffen ist, kann der Schmerz eine Weile nachlassen und dann stärker zurückkehren. Wir empfehlen einen Untersuchungstermin.</p>
<p><strong>Wenn ich ein Antibiotikum beginne, vergeht der Schmerz?</strong><br>Antibiotika können bei manchen Infektionen ergänzend zur Behandlung verordnet werden, sind aber allein keine Lösung und sollten nicht eigenmächtig begonnen werden. Die Schmerzursache wird meist durch einen mechanischen Eingriff beseitigt (Eröffnen des Kanals, Entlastung und Ähnliches). Unnötige Antibiotikaeinnahme erschwert die Diagnose und trägt zur Resistenzbildung bei.</p>
<p><strong>Soll ich bei nachts beginnenden Zahnschmerzen bis zum Morgen warten?</strong><br>Lässt sich der Schmerz mit Medikamenten beherrschen und liegt keines der oben genannten Notfallzeichen vor, kann am Morgen ein Termin vereinbart werden. Bestehen jedoch Schwellung, Fieber, Schluckbeschwerden oder Atemnot, warten Sie nicht bis zum Morgen, sondern stellen Sie sich in der nächstgelegenen Notaufnahme vor.</p>
<p><strong>Der Schmerz ist weg, aber am Zahnfleisch ist ein kleines Bläschen — ist das wichtig?</strong><br>Dieses Bläschen kann darauf hinweisen, dass die Entzündung sich einen eigenen Abflussweg gesucht hat. Ein Nachlassen des Schmerzes bedeutet keine Heilung; der Prozess kann still fortschreiten. Wir empfehlen einen Termin zur Beurteilung.</p>
<h2>Regionale Beurteilung</h2>
<p>In unserer Praxis an der Verbindung Beylikdüzü–Esenyurt haben bei Notfallvorstellungen die sichere Beseitigung des Schmerzes und die Kontrolle der Infektion Vorrang. Der definitive Behandlungsplan wird nach Abklingen des akuten Zustands gemeinsam mit der Patientin oder dem Patienten erstellt.</p>
<p><a href="/de/agiz-dis-sagligi/">Mund- und Zahngesundheit</a> &middot; <a href="/de/kanal-tedavisi/">Wurzelkanalbehandlung</a> &middot; <a href="/de/dis-curugu-kompozit-dolgu/">Karies und Kompositfüllungen</a> &middot; <a href="/de/iletisim">Termin und Kontakt</a></p>',
'Was in den ersten 24 Stunden bei starken Zahnschmerzen zu tun und zu vermeiden ist und bei welchen Anzeichen Sie sofort Hilfe suchen sollten.',
'Zahnärztliche Notfälle: Die ersten 24 Stunden | MSc. Dt. Mehmet Taş',
'DE' FROM pages WHERE link = 'acil-dis-agrisinda-ilk-24-saat';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Zahnbehandlung in der Schwangerschaft: sicher und wann?',
'<p>In der Schwangerschaft können Untersuchung, professionelle Zahnreinigung, Füllungen, Wurzelkanalbehandlungen und notwendige Zahnentfernungen mit geeigneten Vorkehrungen durchgeführt werden. Zustände wie Schmerzen, Schwellung oder Infektion sollten nicht aufgeschoben werden; eine unbehandelte Infektion kann für Mutter und Kind ein größeres Risiko darstellen. Nicht zwingende ästhetische Eingriffe werden in der Regel auf die Zeit nach der Geburt verschoben. Es ist wichtig, bei jedem Termin mitzuteilen, dass Sie schwanger sind und in welcher Schwangerschaftswoche.</p>
<h2>Was verändert sich in der Schwangerschaft im Mund?</h2>
<table>
<thead><tr><th>Veränderung</th><th>Erläuterung</th></tr></thead>
<tbody>
<tr><td>Schwangerschaftsgingivitis</td><td>Hormonelle Veränderungen machen das Zahnfleisch empfindlicher gegenüber Plaque; Rötung, Schwellung und Bluten beim Putzen sind häufig.</td></tr>
<tr><td>Knötchen am Zahnfleisch</td><td>Bei manchen kann sich am Zahnfleisch ein gutartiges, leicht blutendes rotes Knötchen bilden. Es bildet sich meist nach der Geburt zurück; dennoch sollte es zahnärztlich beurteilt werden.</td></tr>
<tr><td>Erhöhtes Kariesrisiko</td><td>Häufiges Naschen, Übelkeit und Erbrechen können den Säurekontakt erhöhen und die Mundpflege beeinträchtigen, was das Kariesrisiko steigert.</td></tr>
<tr><td>Schmelzerosion</td><td>Wiederholtes Erbrechen kann zu säurebedingtem Abtrag an den Zahnoberflächen führen.</td></tr>
</tbody>
</table>
<p>Es gibt Studien, die bei werdenden Müttern einen Zusammenhang zwischen Zahnfleischerkrankungen und Frühgeburt berichten; dass eine Zahnfleischbehandlung in der Schwangerschaft eine Frühgeburt verhindert, ist jedoch nicht gesichert nachgewiesen. Die Zahnfleischbehandlung ist für die Mundgesundheit der Mutter wichtig und sollte zu diesem Zweck erfolgen.</p>
<h2>Planung nach Trimester</h2>
<table>
<thead><tr><th>Zeitraum</th><th>Allgemeines Vorgehen</th></tr></thead>
<tbody>
<tr><td>1. Trimester (1.–13. Woche)</td><td>Untersuchung und Reinigung sind möglich. Da Übelkeit ausgeprägt sein kann, lassen sich längere Eingriffe, sofern nicht dringlich, in den nächsten Zeitraum legen. Notfälle werden nicht aufgeschoben.</td></tr>
<tr><td>2. Trimester (14.–27. Woche)</td><td>Für viele werdende Mütter der angenehmste Zeitraum. Erforderliche Füllungen, <a href="/de/kanal-tedavisi/">Wurzelkanalbehandlungen</a> und Zahnfleischbehandlungen werden meist in diesen Zeitraum gelegt.</td></tr>
<tr><td>3. Trimester (ab der 28. Woche)</td><td>Erforderliche Behandlungen sind möglich; da längeres Liegen auf dem Rücken Unwohlsein und einen Blutdruckabfall verursachen kann, werden die Termine kurz gehalten und auf die Lagerung wird geachtet.</td></tr>
</tbody>
</table>
<p>Das ist ein allgemeiner Rahmen; der Plan wird individuell nach dem Verlauf der Schwangerschaft und den Empfehlungen Ihrer Frauenärztin oder Ihres Frauenarztes festgelegt.</p>
<h2>Worauf wird in der Praxis geachtet?</h2>
<p><img src="/assets/uploads/images/ts79-01-unit-pozisyonu.webp" alt="Eine schwangere Patientin sitzt gestützt und leicht nach links gedreht auf dem Behandlungsstuhl" loading="lazy" /></p>
<table>
<thead><tr><th>Thema</th><th>Erläuterung</th></tr></thead>
<tbody>
<tr><td>Information</td><td>Schwangerschaftswoche, eingenommene Vitamine und Medikamente, eine etwaige Risikoschwangerschaft und die Empfehlungen Ihrer Frauenärztin oder Ihres Frauenarztes sollten mitgeteilt werden.</td></tr>
<tr><td>Lokalanästhesie</td><td>Die in der Zahnbehandlung verwendeten Lokalanästhetika können in der Schwangerschaft in den zahnärztlich als geeignet erachteten Dosen eingesetzt werden. Eine Behandlung unter Schmerzen kann mehr Stress verursachen als die Anästhesie.</td></tr>
<tr><td>Röntgen</td><td>Wird nur angefertigt, wenn es für die Diagnose wirklich erforderlich ist. Die Strahlendosis zahnärztlicher Aufnahmen ist sehr gering und sie werden mit Schutzmaßnahmen durchgeführt.</td></tr>
<tr><td>Medikamente</td><td>Sind ein Schmerzmittel oder ein Antibiotikum nötig, werden in der Schwangerschaft als geeignet geltende Präparate gewählt, bei Bedarf nach Rücksprache mit Ihrer Frauenärztin oder Ihrem Frauenarzt. Nehmen Sie keine Medikamente auf eigene Faust ein.</td></tr>
<tr><td>Lagerung</td><td>In der fortgeschrittenen Schwangerschaft ist es angenehmer, leicht aufrecht und nach links gedreht zu sitzen statt flach auf dem Rücken. Sagen Sie sofort Bescheid, wenn Ihnen schwindelig oder übel wird oder Sie Atemnot verspüren.</td></tr>
<tr><td>Termindauer</td><td>Kurze Termine mit häufigen Pausen werden bevorzugt.</td></tr>
</tbody>
</table>
<p><img src="/assets/uploads/images/ts79-02-gebelik-bilgisi-paylasimi.webp" alt="Eine schwangere Patientin teilt Angaben zu Schwangerschaft und Gesundheit mit dem Zahnarzt" loading="lazy" /></p>
<h2>Pflege zu Hause und Übelkeit</h2>
<p><img src="/assets/uploads/images/ts79-03-bulanti-sonrasi-calkalama.webp" alt="Ausspülen des Mundes mit Wasser nach Übelkeit in der Schwangerschaft" loading="lazy" /></p>
<p>Empfohlen werden zweimal tägliches Putzen mit fluoridhaltiger Zahnpasta und einer weichen Bürste sowie tägliche Interdentalreinigung. Hören Sie nicht auf zu putzen, weil das Zahnfleisch blutet; die Blutung ist meist ein Zeichen für Plaque und geht mit regelmäßiger, sanfter Reinigung zurück.</p>
<p>Spülen Sie nach dem Erbrechen den Mund mit Wasser aus, statt sofort zu putzen, und warten Sie eine Weile; durch Säure erweichter Schmelz wird von der Bürste leichter abgetragen. Wird Ihnen beim Putzen übel, können Sie eine Bürste mit kleinem Kopf und eine weniger stark aromatisierte Zahnpasta versuchen. Wenn Sie häufig etwas essen müssen, können statt zuckerhaltiger und klebriger Speisen Käse, Joghurt oder Gemüse gewählt werden.</p>
<p><img src="/assets/uploads/images/ts79-04-yumusak-fircayla-fircalama.webp" alt="Sanftes Putzen mit einer weichen Bürste bei empfindlichem Zahnfleisch in der Schwangerschaft" loading="lazy" /></p>
<h2>Eingriffe, die aufgeschoben werden können</h2>
<p>Ästhetische Eingriffe wie <a href="/de/dis-beyazlatma/">Zahnaufhellung</a>, Veneers oder Kronen, nicht zwingende <a href="/de/dental-implant-tedavisi/">Implantatchirurgie</a> und umfassende ästhetische Erneuerungen werden in der Regel auf die Zeit nach der Geburt gelegt. Das bedeutet nicht, dass diese Eingriffe zwangsläufig schädlich sind; Ziel ist, bei nicht dringlichen Maßnahmen unnötige Medikamente und lange Sitzungen zu vermeiden.</p>
<p><strong>Was nicht aufgeschoben werden sollte:</strong> starke Zahnschmerzen, Gesichtsschwellung, ein Abszess, Fieber, Unfälle und Frakturen. In diesen Fällen sollten Sie sich unabhängig von der Schwangerschaftswoche ohne Abwarten vorstellen.</p>
<h2>Häufig gestellte Fragen</h2>
<p><strong>Ist in der Schwangerschaft eine Betäubung möglich?</strong><br>Ja. Die in der Zahnbehandlung verwendeten Lokalanästhetika können in der Schwangerschaft in den zahnärztlich festgelegten Dosen eingesetzt werden. Teilen Sie unbedingt mit, dass Sie schwanger sind, und nennen Sie besondere Umstände.</p>
<p><strong>Dürfen in der Schwangerschaft Röntgenaufnahmen gemacht werden?</strong><br>Wenn es für die Diagnose erforderlich ist, ja. Die Dosis zahnärztlicher Aufnahmen ist sehr gering und sie werden mit Schutzmaßnahmen durchgeführt. Nicht erforderliche Aufnahmen werden aufgeschoben.</p>
<p><strong>Mein Zahnfleisch blutet beim Putzen — ist das normal?</strong><br>In der Schwangerschaft kommt das häufig vor, sollte aber nicht auf sich beruhen bleiben. Putzen Sie weiter sanft und regelmäßig, reinigen Sie die Zahnzwischenräume und vereinbaren Sie einen Kontrolltermin; bei Bedarf kann eine professionelle Zahnreinigung erfolgen.</p>
<p><strong>Dürfen in der Schwangerschaft Zähne entfernt werden?</strong><br>Wenn es erforderlich ist, ja. Die Entfernung eines Zahns, der eine Infektion oder starke Schmerzen verursacht, sollte nicht aufgeschoben werden. Die Planung richtet sich nach Schwangerschaftswoche und Allgemeinzustand.</p>
<p><strong>Kann ich während der Stillzeit behandelt werden?</strong><br>Ja. Maßnahmen wie Lokalanästhesie und Füllungen stehen dem Stillen nicht entgegen. Wird ein Medikament benötigt, sagen Sie Ihrer Zahnärztin oder Ihrem Zahnarzt, dass Sie stillen.</p>
<h2>Regionale Beurteilung</h2>
<p>In unserer Praxis an der Verbindung Beylikdüzü–Esenyurt erfolgt die Behandlungsplanung für werdende Mütter durch die gemeinsame Beurteilung von Schwangerschaftszeitraum, klinischen Befunden, Allgemeinzustand und den Empfehlungen Ihrer Frauenärztin oder Ihres Frauenarztes. MSc. Dt. Mehmet Taş und sein Team planen Termindauer und Sitzposition auf dem Behandlungsstuhl nach Ihrer Schwangerschaftswoche.</p>
<p><a href="/de/agiz-dis-sagligi/">Mund- und Zahngesundheit</a> &middot; <a href="/de/kanal-tedavisi/">Wurzelkanalbehandlung</a> &middot; <a href="/de/iletisim">Termin und Kontakt</a></p>',
'Ist eine Zahnbehandlung in der Schwangerschaft möglich, wann ist der beste Zeitpunkt, warum blutet das Zahnfleisch, sind Betäubung und Röntgen sicher?',
'Zahnbehandlung in der Schwangerschaft | MSc. Dt. Mehmet Taş',
'DE' FROM pages WHERE link = 'hamilelikte-dis-tedavisi';


INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Kinderzahnheilkunde: Erstuntersuchung, Karies an Milchzähnen und Vorsorge',
'<p>Die erste zahnärztliche Untersuchung eines Kindes wird innerhalb von sechs Monaten nach dem Durchbruch des ersten Milchzahns oder spätestens zum ersten Geburtstag empfohlen. Der Zweck dieses Besuchs ist meist nicht die Behandlung, sondern das Kariesrisiko zu beurteilen, der Familie altersgerechte Hinweise zu Pflege und Ernährung zu geben und dem Kind zu ermöglichen, sich an die Praxis zu gewöhnen. Wird später eine Behandlung nötig, lässt sie sich bei einem Kind, das früh Kontakt hatte, meist leichter durchführen.</p>
<p><img src="/assets/uploads/images/ts87-01-ilk-muayene-kucuk-cocuk.webp" alt="Erstuntersuchung eines kleinen Kindes auf dem Behandlungsstuhl" loading="lazy"  /></p>
<p>In unserer Praxis werden unsere kleinen Patientinnen und Patienten von unserer Fachzahnärztin bzw. unserem Fachzahnarzt für Kinderzahnheilkunde beurteilt und behandelt.</p>
<h2>Warum sind Milchzähne wichtig?</h2>
<p>Milchzähne sind nicht nur eine vorübergehende Zahnreihe; sie dienen dem Kauen, der Sprachentwicklung und dem Platzhalten für die bleibenden Zähne. In die Lücke eines früh verlorenen Milchzahns können Nachbarzähne wandern, wodurch sich der für den bleibenden Zahn nötige Platz verengt.</p>
<table>
<thead><tr><th>Funktion</th><th>Erläuterung</th></tr></thead>
<tbody>
<tr><td>Kauen und Ernährung</td><td>Ein schmerzender oder kariöser Zahn kann das Kauen und die Vielfalt der Ernährung einschränken.</td></tr>
<tr><td>Sprachentwicklung</td><td>Die Frontzähne tragen zur Bildung bestimmter Laute bei.</td></tr>
<tr><td>Platzhalten</td><td>Jeder Milchzahn hält den Platz für den darunter liegenden bleibenden Zahn. Bei frühem Verlust kann sich der Platz verengen.</td></tr>
<tr><td>Kieferentwicklung</td><td>Ausgewogenes Kauen unterstützt die Entwicklung von Kiefer und Muskulatur.</td></tr>
</tbody>
</table>
<h2>Wie beginnt Karies an einem Milchzahn und wie erkennt man sie?</h2>
<p>Der Schmelz eines Milchzahns ist dünner als der eines bleibenden Zahns; deshalb kann <a href="/de/dis-curugu-kompozit-dolgu/">Karies</a> bei manchen Kindern schneller fortschreiten. In der Frühphase können Schmerzen fehlen, weshalb regelmäßige Kontrollen wichtiger sind, als auf Schmerzen zu warten.</p>
<ul>
<li>Kreidig weiße Flecken nahe dem Zahnfleischrand (ein Frühzeichen)</li>
<li>Braune bis schwarze Verfärbung, Einbrüche der Oberfläche</li>
<li>Empfindlichkeit auf Kaltes, Warmes oder Süßes</li>
<li>Das Kind vermeidet es, auf einer Seite zu kauen</li>
<li>Schwellung des Zahnfleischs, Gesichtsschwellung oder Fieber — in diesem Fall nicht abwarten</li>
</ul>
<p><img src="/assets/uploads/images/ts87-02-sut-disi-curuk-asamalari.webp" alt="Die Stadien der Karies an einem Milchzahn vom ersten weißen Fleck bis zur fortgeschrittenen Läsion" loading="lazy"  /></p>
<p><strong>Fläschchen und nächtliches Stillen:</strong> Zuckerhaltige Getränke oder Fruchtsaft aus dem Fläschchen während des Schlafs sowie häufiges nächtliches Stillen werden mit rasch fortschreitender Karies an den Frontzähnen in Verbindung gebracht. Andere Getränke als Wasser sollten vor und während des Schlafs nicht gegeben werden.</p>
<h2>Mundpflege nach Alter und Fluorid</h2>
<p>Das Putzen beginnt, sobald der erste Zahn im Mund sichtbar ist. Bei kleinen Kindern putzen die Eltern; im Schulalter putzt das Kind selbst, doch Aufsicht und Unterstützung durch die Eltern bleiben bestehen.</p>
<table>
<thead><tr><th>Alter</th><th>Vorgehen</th></tr></thead>
<tbody>
<tr><td>Erster Zahn – 3 Jahre</td><td>Zweimal täglich mit einer weichen Bürste mit kleinem Kopf. Fluoridhaltige Zahnpasta in der Menge eines Reiskorns (ein dünner Film). Die Eltern putzen.</td></tr>
<tr><td>3 – 6 Jahre</td><td>Zweimal täglich mit einer erbsengroßen Menge fluoridhaltiger Zahnpasta. Das Kind putzt, die Eltern putzen nach und beaufsichtigen. Das Kind lernt, die Zahnpasta auszuspucken und nicht nachzuspülen.</td></tr>
<tr><td>Ab 6 Jahren</td><td>Zweimal täglich putzen, an den Kontaktflächen Zahnseide. Die elterliche Aufsicht besteht in abnehmendem Maß fort.</td></tr>
<tr><td>Alle Altersgruppen</td><td>Die Zahnpastatube wird außerhalb der Reichweite des Kindes aufbewahrt; Zahnpasta sollte nicht verschluckt werden.</td></tr>
</tbody>
</table>
<p>Die geeignete Zahnpastamenge und der Fluoridbedarf werden zahnärztlich nach Alter und Kariesrisiko des Kindes festgelegt.</p>
<p><img src="/assets/uploads/images/ts87-03-yasa-gore-macun-miktari.webp" alt="Zahnpastamenge nach Alter: Vergleich von Reiskorn und Erbse" loading="lazy"  /></p>
<h2>Vorbeugende Maßnahmen</h2>
<table>
<thead><tr><th>Maßnahme</th><th>Wann kommt sie in Betracht?</th></tr></thead>
<tbody>
<tr><td>Fissurenversiegelung</td><td>Wenn tiefe Rillen auf den Kauflächen der Backenzähne schwer zu reinigen sind; wird nach dem Durchbruch und bei kariesfreiem Zahn angewendet.</td></tr>
<tr><td>Fluoridlack</td><td>Kann je nach Beurteilung des Kariesrisikos in bestimmten Abständen in der Praxis aufgetragen werden. Die Häufigkeit ist nicht für jedes Kind gleich.</td></tr>
<tr><td>Ernährungsberatung</td><td>Zuckerhäufigkeit, Snackgewohnheiten und Getränkeauswahl werden durchgesehen.</td></tr>
<tr><td>Putzanleitung</td><td>Die Technik wird nach Alter und Geschicklichkeit des Kindes gezeigt; die Rolle der Eltern wird festgelegt.</td></tr>
</tbody>
</table>
<p>Fissurenversiegelungen, Fluoridanwendungen, Platzhalter und vorbeugende Kunststofffüllungen werden alle in unserer Praxis durchgeführt.</p>
<p><img src="/assets/uploads/images/ts87-04-fissur-orturucu.webp" alt="Eine Fissurenversiegelung auf der Kaufläche eines Backenzahns" loading="lazy"  /></p>
<h2>Zahnverlust und Platzhalter</h2>
<p>Geht ein Milchzahn durch Karies oder einen Unfall vorzeitig verloren, kann ein Platzhalter erwogen werden, um das Wandern der Nachbarzähne in die Lücke zu begrenzen. Nicht bei jedem frühen Verlust ist ein Platzhalter nötig; die Entscheidung richtet sich danach, welcher Zahn verloren ging, nach dem Alter des Kindes, dem Entwicklungsstand des darunter liegenden bleibenden Zahns und den Röntgenbefunden.</p>
<h2>Das Kind auf den Termin vorbereiten</h2>
<ul>
<li>Statt vor dem Termin ausführliche Angstgeschichten zu erzählen, empfehlen wir, den Besuch ruhig einzuführen, etwa als „Zähne zählen“.</li>
<li>Auf feste Zusagen wie „das tut nicht weh“ oder „es gibt keine Spritze“ sollte verzichtet werden, um das Vertrauen zu wahren.</li>
<li>Einen Termin zu einer Zeit zu legen, in der das Kind ausgeruht ist, erleichtert die Mitarbeit.</li>
<li>Frühere unangenehme Erfahrungen, ein etwaiger besonderer Betreuungsbedarf und eingenommene Medikamente sollten vor dem Termin mitgeteilt werden.</li>
</ul>
<p>Bei Kindern mit ausgeprägter Angst wird ein schrittweises Gewöhnungsvorgehen gewählt. Bei Kindern, denen die Mitarbeit schwerfällt, die sehr jung sind oder eine umfangreiche Behandlung benötigen, erfolgt die Behandlung unter Sedierung; die Sedierung wird in unserer Praxis durchgeführt. Ist eine Vollnarkose erforderlich, erfolgt die Behandlung in den Krankenhäusern, mit denen wir zusammenarbeiten, in Begleitung einer Anästhesistin oder eines Anästhesisten und ebenfalls durch unsere Fachzahnärztin bzw. unseren Fachzahnarzt für Kinderzahnheilkunde. Das Vorgehen wird nach Beurteilung von Alter, Allgemeinzustand und Behandlungsumfang gemeinsam mit der Familie entschieden.</p>
<h2>Häufig gestellte Fragen</h2>
<p><strong>Wann sollte ich mein Kind zum ersten Mal zur Zahnärztin oder zum Zahnarzt bringen?</strong><br>Innerhalb von sechs Monaten nach dem Durchbruch des ersten Milchzahns, spätestens zum ersten Geburtstag. Auch ohne Beschwerden dient dieser Besuch dazu, das Kariesrisiko zu beurteilen und einen Pflegeplan aufzustellen.</p>
<p><strong>Milchzähne fallen ohnehin aus — muss Karies behandelt werden?</strong><br>Ja. Unbehandelte Karies kann zu Schmerzen, Infektionen, Ernährungsproblemen und frühem Zahnverlust führen; ein früher Verlust kann die Position des bleibenden Zahns beeinflussen.</p>
<p><strong>Ist fluoridhaltige Zahnpasta für Kinder sicher?</strong><br>In altersgerechter Menge und unter Aufsicht angewendet gilt fluoridhaltige Zahnpasta als nützlich für den Kariesschutz. Wichtig ist, dass die Menge zum Alter passt und die Zahnpasta nicht verschluckt wird.</p>
<p><strong>Zwischen den Zähnen meines Kindes sind Lücken — ist das ein Problem?</strong><br>Lücken im Milchgebiss sind meist zu erwarten und schaffen Platz für die bleibenden Zähne. Dennoch erfolgt die Beurteilung durch eine Untersuchung.</p>
<p><strong>Schaden Daumenlutschen oder Schnuller den Zähnen?</strong><br>Je nach Dauer und Intensität können sie das Bissverhältnis beeinflussen. Besteht die Gewohnheit fort, wird ein altersgerechtes Vorgehen zum Abgewöhnen erwogen.</p>
<p><strong>Sind Kinderzahnheilkunde und Kieferorthopädie dasselbe?</strong><br>Nein. Die Kinderzahnheilkunde umfasst Karies, Vorsorge und die Behandlung von Milchzähnen; die Stellung von Zähnen und Kiefern ist Gegenstand der kieferorthopädischen Beurteilung.</p>
<h2>Regionale Beurteilung</h2>
<p>In unserer Praxis an der Verbindung Beylikdüzü–Esenyurt haben bei Kindern das erste Kennenlernen in einer schmerzfreien Zeit und das frühe Erkennen des Kariesrisikos Vorrang. Der Behandlungsbedarf wird durch die gemeinsame Beurteilung von klinischer Untersuchung, Alter des Kindes, Grad der Mitarbeit und erforderlichen Röntgenbefunden geplant.</p>
<p><a href="/de/agiz-dis-sagligi/">Mund- und Zahngesundheit</a> &middot; <a href="/de/dis-curugu-kompozit-dolgu/">Karies und Kompositfüllungen</a> &middot; <a href="/de/cocuklarda-dis-travmasi/">Zahnunfälle bei Kindern</a> &middot; <a href="/de/kanal-tedavisi/">Wurzelkanalbehandlung</a> &middot; <a href="/de/iletisim">Termin und Kontakt</a></p>',
'Wann sollte ein Kind zum ersten Mal zum Zahnarzt, warum ist Karies an Milchzähnen wichtig, wann sind Fluorid und Platzhalter nötig?',
'Kinderzahnheilkunde | MSc. Dt. Mehmet Taş',
'DE' FROM pages WHERE link = 'cocuk-dis-hekimligi';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Zahnunfälle bei Kindern: Erste Hilfe bei gebrochenem oder ausgeschlagenem Zahn',
'<h2>Die ersten 30 Minuten: kurz zusammengefasst</h2>
<ol>
<li>Bleiben Sie ruhig, setzen Sie das Kind hin und üben Sie mit einer sauberen Mullkompresse sanften Druck auf die blutende Stelle aus.</li>
<li>Ist ein Zahn vollständig herausgeschlagen, fassen Sie ihn an der Krone (dem weißen, sichtbaren Teil) an. Reiben Sie die Wurzel nicht mit der Hand, bürsten Sie sie nicht und lassen Sie sie nicht austrocknen.</li>
<li><strong>Bei einem bleibenden Zahn:</strong> Ist er verschmutzt, spülen Sie ihn einige Sekunden vorsichtig mit Milch oder Kochsalzlösung ab; setzen Sie den Zahn nach Möglichkeit in sein Fach zurück. Gelingt das nicht, bewahren Sie ihn in Milch auf.</li>
<li><strong>Bei einem Milchzahn</strong> versuchen Sie nicht, ihn wieder einzusetzen. Das könnte den darunter liegenden bleibenden Zahn schädigen.</li>
<li>Kommen Sie ohne Verzug in die Praxis. Bei einem ausgeschlagenen bleibenden Zahn sind die ersten 30–60 Minuten entscheidend.</li>
</ol>
<p><strong>Rufen Sie an, bevor Sie losfahren:</strong> <a href="tel:+905435588519">+90 543 558 85 19</a> &middot; <a href="https://wa.me/905435588519" target="_blank" rel="noopener">WhatsApp</a> — eine Vorankündigung verkürzt die Vorbereitungszeit.</p>
<p><img src="/assets/uploads/images/ts88-01-dis-nasil-tutulur.webp" alt="Einen ausgeschlagenen Zahn an der Krone halten, ohne die Wurzel zu berühren" loading="lazy"  /></p>
<h2>Milchzahn oder bleibender Zahn?</h2>
<p>Das weitere Vorgehen hängt vollständig von dieser Unterscheidung ab. Im Allgemeinen brechen die ersten bleibenden Schneidezähne zwischen dem 6. und 8. Lebensjahr durch; bei einem jüngeren Kind ist ein herausgeschlagener Frontzahn höchstwahrscheinlich ein Milchzahn. Wenn Sie unsicher sind, werfen Sie den Zahn nicht weg, sondern bringen Sie ihn in Milch mit.</p>
<table>
<thead><tr><th>Situation</th><th>Milchzahn</th><th>Bleibender Zahn</th></tr></thead>
<tbody>
<tr><td>Vollständig herausgeschlagen</td><td>Wird nicht wieder eingesetzt. Bringen Sie den Zahn mit; das Kind wird beurteilt.</td><td>Wird nach Möglichkeit sofort zurückgesetzt; andernfalls in Milch mitgebracht.</td></tr>
<tr><td>Gebrochen</td><td>Das Bruchstück mitbringen; scharfe Kanten und eine Pulpaeröffnung werden beurteilt.</td><td>Das Bruchstück mitbringen; in manchen Fällen kann es wieder angeklebt werden.</td></tr>
<tr><td>Verlagert</td><td>Position und Nähe zum bleibenden Zahn werden beurteilt.</td><td>Eine Reposition und Schienung können erforderlich sein.</td></tr>
<tr><td>Dringlichkeit</td><td>Beurteilung am selben Tag</td><td>Minuten zählen</td></tr>
</tbody>
</table>
<p><strong>Warum wird ein Milchzahn nicht wieder eingesetzt?</strong> Die Wurzel eines Milchzahns liegt sehr nahe an der darunter heranwachsenden Anlage des bleibenden Zahns. Der Versuch, den Zahn zurückzusetzen, kann die Entwicklung und Farbe des bleibenden Zahns dauerhaft beeinträchtigen.</p>
<p><img src="/assets/uploads/images/ts88-02-sut-disi-daimi-dis-farki.webp" alt="Querschnitt mit dem Unterschied in Wurzel und Lage zwischen Milchzahn und bleibendem Zahn" loading="lazy"  /></p>
<h2>Ein vollständig ausgeschlagener bleibender Zahn</h2>
<p>Dies ist die zeitkritischste Form des Zahnunfalls. Der Erhalt der lebenden Zellen auf der Wurzeloberfläche beeinflusst das Ergebnis unmittelbar; deshalb darf der Zahn keinesfalls austrocknen.</p>
<h3>Was zu tun ist</h3>
<ul>
<li>Den Zahn nur an der Krone anfassen; die Wurzeloberfläche nicht berühren.</li>
<li>Bei sichtbarem Schmutz einige Sekunden mit Milch oder Kochsalzlösung abspülen. Nicht reiben, keine Seife und kein Desinfektionsmittel verwenden.</li>
<li>Den Zahn nach Möglichkeit vorsichtig und richtig herum in sein eigenes Fach zurücksetzen; das Kind hält ihn fest, indem es auf eine saubere Mullkompresse beißt.</li>
<li>Lässt er sich nicht zurücksetzen, den Zahn in Milch transportieren. Ist keine Milch vorhanden, Kochsalzlösung verwenden.</li>
<li>Ohne Zeitverlust in die Praxis fahren und vorher anrufen.</li>
</ul>
<h3>Was nicht zu tun ist</h3>
<ul>
<li>Den Zahn an der Wurzel anfassen oder die Wurzel bürsten, kratzen oder abwischen</li>
<li>Den Zahn in ein trockenes Taschentuch, eine Serviette oder die Hosentasche stecken</li>
<li>Den Zahn längere Zeit in Leitungswasser liegen lassen</li>
<li>Das Kind den Zahn im Mund transportieren lassen, wenn es nicht bei vollem Bewusstsein ist oder erbricht</li>
</ul>
<table>
<thead><tr><th>Aufbewahrungsmedium</th><th>Eignung</th></tr></thead>
<tbody>
<tr><td>Milch</td><td>Zu Hause und unterwegs am leichtesten verfügbar und geeignet</td></tr>
<tr><td>Kochsalzlösung</td><td>Geeignet; in der Apotheke erhältlich</td></tr>
<tr><td>Der eigene Speichel des Kindes</td><td>Kann vorübergehend verwendet werden, wenn es keine andere Möglichkeit gibt</td></tr>
<tr><td>Leitungswasser</td><td>Nicht geeignet; es schädigt die Zellen der Wurzeloberfläche</td></tr>
<tr><td>Trockene Umgebung (Taschentuch, Hosentasche)</td><td>Nicht geeignet</td></tr>
</tbody>
</table>
<p><img src="/assets/uploads/images/ts88-03-saklama-sivisi-sut.webp" alt="Ein ausgeschlagener Zahn in einem Gefäß mit Milch aufbewahrt" loading="lazy"  /></p>
<h2>Ein gebrochener Zahn</h2>
<p>Die Tiefe des Bruchs bestimmt die Behandlung. Ein kleiner Bruch, der nur den Schmelz betrifft, ist nicht dasselbe wie ein Bruch, bei dem die Pulpa freiliegt. Wird das Bruchstück gefunden, sollte es in Milch oder Kochsalzlösung mitgebracht werden; in ausgewählten Fällen kann es wieder angeklebt werden.</p>
<ul>
<li>Ist auf der Bruchfläche ein rosa oder roter Punkt sichtbar oder blutet es: Die Pulpa kann freiliegen, Sie sollten sich am selben Tag vorstellen.</li>
<li>Schneidet eine scharfe Kante in Zunge oder Lippe, kann sie vorübergehend mit weichem Wachs oder sauberer Mullkompresse abgedeckt werden.</li>
<li>Auch wenn kein Bruch sichtbar ist, kann ein Zahn nach einem Schlag später eine Verfärbung zeigen oder schmerzen; eine Nachbeobachtung ist nötig.</li>
</ul>
<p><img src="/assets/uploads/images/ts88-04-kirik-dis-katmanlari.webp" alt="Querschnitt eines gebrochenen Zahns mit Schmelz-, Dentin- und Pulpaschicht" loading="lazy"  /></p>
<h2>Ein verlagerter oder eingeschlagener Zahn</h2>
<p>Ein Zahn kann seine Position verändern, ohne vollständig herauszufallen: Er kann nach vorn oder hinten wandern, länger wirken oder in den Knochen hineingedrückt werden. Versuchen Sie in diesen Fällen nicht, den Zahn mit Kraft zurückzuschieben; geben Sie dem Kind weiche Kost und bringen Sie es in die Praxis. Die Beurteilung erfolgt durch klinische Untersuchung und die erforderlichen Röntgenaufnahmen.</p>
<h2>Wann sofort ins Krankenhaus</h2>
<p>Bei folgenden Befunden sollten Sie sich zuerst in einer Notaufnahme vorstellen; die zahnärztliche Beurteilung folgt danach:</p>
<ul>
<li>Bewusstlosigkeit, Schläfrigkeit, wiederholtes Erbrechen, Schwindel</li>
<li>Nicht stillbare Blutung</li>
<li>Deutliche Formveränderung des Kiefers, Unfähigkeit, den Mund zu öffnen oder zu schließen</li>
<li>Blutung aus Nase oder Ohr, Sehveränderungen</li>
<li>Ausgedehnte Gesichtsverletzung oder eine tiefe Wunde</li>
<li>Eine bekannte Gerinnungsstörung oder die Einnahme von Gerinnungshemmern</li>
</ul>
<p>Wie der Unfall geschehen ist (Sturz, Aufprall, Verkehrsunfall, Sport) und der Tetanus-Impfstatus des Kindes sollten der behandelnden Person mitgeteilt werden.</p>
<h2>Nachsorge nach einem Unfall</h2>
<p>Die Erstversorgung bei einem Zahnunfall ist der Anfang des Prozesses. An einem Zahn, der einen Schlag erhalten hat, können Wochen, manchmal Monate später eine Verfärbung, ein Bläschen am Zahnfleisch, Schmerzen beim Zubeißen oder eine Lockerung auftreten. Verunfallte Zähne werden deshalb in bestimmten Abständen klinisch und röntgenologisch beobachtet. Die Nachsorgetermine einzuhalten ermöglicht es, ein spät auftretendes Problem früh zu erkennen.</p>
<p>Bei Kindern im Wachstum richten sich die Behandlungsmöglichkeiten nach einem Unfall nach dem Stand der Wurzelentwicklung; der Plan wird daher nach Alter des Kindes und Röntgenbefunden individuell erstellt. Sowohl die Notfallversorgung als auch die langfristige Nachsorge von Zahnunfällen bei Kindern werden in unserer Praxis von unserer Fachzahnärztin bzw. unserem Fachzahnarzt für Kinderzahnheilkunde geführt.</p>
<h2>Häufig gestellte Fragen</h2>
<p><strong>Kann ich einen ausgeschlagenen Zahn selbst wieder einsetzen?</strong><br>Bei einem bleibenden Zahn ist es angebracht, ihn vorsichtig zurückzusetzen, wenn das Kind ruhig und der Zahn nicht stark verschmutzt ist. Ein Milchzahn wird nicht wieder eingesetzt. Wenn Sie unsicher sind, legen Sie den Zahn in Milch und kommen Sie ohne Verzug in die Praxis.</p>
<p><strong>Darf ich den Zahn mit Wasser abwaschen?</strong><br>Leitungswasser ist nicht geeignet. Nur bei sichtbarem Schmutz einige Sekunden mit Milch oder Kochsalzlösung abspülen; die Wurzel niemals reiben.</p>
<p><strong>Wie schnell muss ich kommen?</strong><br>Bei einem ausgeschlagenen bleibenden Zahn sind die ersten 30–60 Minuten entscheidend. Auch wenn diese Zeit verstrichen ist, sollte der Zahn mitgebracht werden, sofern er in einem geeigneten Medium aufbewahrt wurde; eine Beurteilung erfolgt weiterhin.</p>
<p><strong>Ein Milchzahn ist ausgefallen und ein neuer kommt nach. Soll ich trotzdem kommen?</strong><br>Ja. Es muss beurteilt werden, ob der darunter liegende bleibende Zahn betroffen ist und ob Verletzungen von Zahnfleisch und Kiefer vorliegen.</p>
<p><strong>Der Zahn ist dunkler geworden — bin ich zu spät?</strong><br>Eine Verfärbung nach einem Unfall kann Wochen oder Monate später auftreten. Eine Beurteilung ist nötig; nicht jede Verfärbung bedeutet dasselbe.</p>
<p><strong>Ich habe das Bruchstück aufgehoben — nützt das etwas?</strong><br>In manchen Fällen kann das Bruchstück wieder angeklebt werden. Bringen Sie es in Milch oder Kochsalzlösung mit, damit es nicht austrocknet.</p>
<h2>Regionale Beurteilung</h2>
<p>In unserer Praxis an der Verbindung Beylikdüzü–Esenyurt haben bei Kindern mit einem Zahnunfall die Bestimmung des Verletzungsumfangs und die unverzügliche Durchführung zeitkritischer Maßnahmen Vorrang. Ein Anruf vor Ihrem Kommen verkürzt die Vorbereitungszeit.</p>
<p><a href="/de/cocuk-dis-hekimligi/">Kinderzahnheilkunde</a> &middot; <a href="/de/agiz-dis-sagligi/">Mund- und Zahngesundheit</a> &middot; <a href="/de/kanal-tedavisi/">Wurzelkanalbehandlung</a> &middot; <a href="/de/dis-curugu-kompozit-dolgu/">Karies und Kompositfüllungen</a> &middot; <a href="/de/iletisim">Termin und Kontakt</a></p>',
'Was in den ersten 30 Minuten bei einem ausgeschlagenen oder gebrochenen Zahn zu tun ist: Milchzahn oder bleibender Zahn, Aufbewahrung und Notfallhinweise.',
'Zahnunfälle bei Kindern | MSc. Dt. Mehmet Taş',
'DE' FROM pages WHERE link = 'cocuklarda-dis-travmasi';

